-- Original platform Reading Aloud tasks. These are global and therefore visible to guests.
INSERT OR IGNORE INTO content_items
(id,content_type,title,school_level,topic,source_url,licence,status,active_version,description,source_attribution,published_at,scope)
VALUES
('r20-speak-p5-library-visit','oral_prompt','A Visit to the School Library','P5','School','https://www.moe.gov.sg/-/media/files/primary/2020-english-language-primary.ashx','owned','published',1,'Original Reading Aloud practice focusing on clear phrasing, pace and expression.','English Mastery original · aligned to MOE English Language Syllabus 2020',CURRENT_TIMESTAMP,'global'),
('r20-speak-p5-helpful-neighbour','oral_prompt','A Helpful Neighbour','P5','Community','https://www.moe.gov.sg/-/media/files/primary/2020-english-language-primary.ashx','owned','published',1,'Original Reading Aloud practice with dialogue-like phrasing and natural emphasis.','English Mastery original · aligned to MOE English Language Syllabus 2020',CURRENT_TIMESTAMP,'global'),
('r20-speak-p6-school-exhibition','oral_prompt','The School Exhibition','P6','School','https://www.moe.gov.sg/-/media/files/primary/2020-english-language-primary.ashx','owned','published',1,'Original Reading Aloud practice requiring confident delivery and appropriate emphasis.','English Mastery original · aligned to MOE English Language Syllabus 2020',CURRENT_TIMESTAMP,'global'),
('r20-speak-p6-small-change','oral_prompt','One Small Change','P6','Environment','https://www.moe.gov.sg/-/media/files/primary/2020-english-language-primary.ashx','owned','published',1,'Original Reading Aloud practice on cause, effect and reflective delivery.','English Mastery original · aligned to MOE English Language Syllabus 2020',CURRENT_TIMESTAMP,'global');

INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status)
VALUES
('r20-speak-p5-library-visit-v1','r20-speak-p5-library-visit',1,'{"mode":"reading_aloud","prompt":"Read the passage aloud clearly. Pause naturally at commas and full stops, and make the final sentence sound thoughtful.","referenceText":"Our class visited the school library to choose books for a new reading corner. Some pupils went straight to the adventure shelf, while others looked for books about animals, space and inventions. I noticed that the librarian was helping a younger pupil find a book that was not too difficult. She explained how to use the pictures, headings and short descriptions to choose a suitable book. Before we left, our teacher reminded us that reading is not a race. A good book gives us time to wonder, learn and think."}','r20-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved'),
('r20-speak-p5-helpful-neighbour-v1','r20-speak-p5-helpful-neighbour',1,'{"mode":"reading_aloud","prompt":"Read the passage aloud as a short story. Use a warm tone when describing the neighbour helping the family.","referenceText":"When a heavy rainstorm began, Maya realised that she had left the windows of her flat open. Her mother was still at work, so Maya hurried home after school. Just as she reached the block, she met a neighbour carrying a small umbrella. The neighbour offered to walk with her and helped close the windows before the rain reached the furniture. Maya thanked her and promised to return the kindness one day. Later that evening, Maya thought about how a small act of help could make a difficult afternoon much easier."}','r20-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved'),
('r20-speak-p6-school-exhibition-v1','r20-speak-p6-school-exhibition',1,'{"mode":"reading_aloud","prompt":"Read the passage aloud as if you are introducing an exhibition to visitors. Stress the important ideas without rushing.","referenceText":"Our school exhibition began with a simple question: how can students make the neighbourhood a better place? One group studied ways to reduce food waste, another designed a safer crossing near the school, and a third collected stories from older residents. The final exhibition did not present one perfect solution. Instead, it showed how different ideas could work together. Visitors were invited to leave suggestions beside each display. By the end of the day, the students understood that useful projects often begin with careful observation and grow through discussion."}','r20-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved'),
('r20-speak-p6-small-change-v1','r20-speak-p6-small-change',1,'{"mode":"reading_aloud","prompt":"Read the passage aloud with a calm, reflective tone. Emphasise the contrast between a small action and its larger effect.","referenceText":"At first, our class wanted to make a dramatic change to the school garden. We imagined building new paths and planting dozens of trees. After speaking to the gardener, however, we realised that the garden needed something simpler. We began by checking which plants were receiving too much water and moved a few pots to better locations. We also started collecting dry leaves for compost. None of these changes looked impressive on their own. After several months, the garden was healthier and easier to care for. We learned that improvement does not always begin with a big idea. Sometimes it begins with noticing one small problem and doing something about it."}','r20-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');

