('r20-speak-p5-classroom-project','oral_prompt','A Classroom Project','P5','Teamwork','https://www.moe.gov.sg/-/media/files/primary/2020-english-language-primary.ashx','owned','published',1,'Original stimulus-based oral conversation practice focused on cooperation and problem solving.','English Mastery original · aligned to MOE English Language Syllabus 2020',CURRENT_TIMESTAMP,'global'),
('r20-speak-p6-community-garden','oral_prompt','The Community Garden','P6','Environment','https://www.moe.gov.sg/-/media/files/primary/2020-english-language-primary.ashx','owned','published',1,'Original stimulus-based oral conversation practice focused on responsibility and community action.','English Mastery original · aligned to MOE English Language Syllabus 2020',CURRENT_TIMESTAMP,'global'),
