INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status)
VALUES
('r20-speak-p5-playground-v1','r20-speak-p5-playground',1,'{"mode":"stimulus","prompt":"Describe what is happening in the scene. Which actions help everyone enjoy the playground safely? Give a reason for your answer.","stimulusAlt":"A school playground during recess: two pupils are waiting for a turn on a slide, a child is helping a younger pupil pick up a dropped water bottle, several pupils are playing a ball game in a marked area, and one pupil is reminding a friend not to run near the steps.","followUpGoals":["describe relevant details","give a clear reason","relate to personal experience","respond to a follow-up question"]}','r20-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved'),
('r20-speak-p5-classroom-project-v1','r20-speak-p5-classroom-project',1,'{"mode":"stimulus","prompt":"Look at the scene and explain how the pupils are working together. What could they do if the group cannot agree on the plan?","stimulusAlt":"A classroom with four pupils preparing a group display: one pupil is drawing a poster, another is arranging pictures, a third is writing labels, and two pupils are discussing which design to use while a teacher observes from nearby.","followUpGoals":["identify actions and roles","suggest a solution","explain a reason","give a personal example"]}','r20-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved'),
('r20-speak-p6-community-garden-v1','r20-speak-p6-community-garden',1,'{"mode":"stimulus","prompt":"Describe the scene and discuss whether children should take responsibility for caring for shared green spaces. Explain your view.","stimulusAlt":"A community garden beside a block of flats: children are watering plants, an adult is checking a compost bin, one pupil is removing litter from a path, and another child is showing a neighbour a sign explaining which plants are ready to harvest.","followUpGoals":["describe relevant details","state and develop a view","consider another perspective","give a relevant example"]}','r20-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved'),
('r20-speak-p6-school-event-v1','r20-speak-p6-school-event',1,'{"mode":"stimulus","prompt":"What are the pupils doing to make the event successful? Which responsibility would you be most willing to take, and why?","stimulusAlt":"A school event in a hall: pupils are welcoming visitors, another pupil is checking a programme, two pupils are arranging chairs, a student is helping a younger child find a classroom, and a teacher is speaking to volunteers near the entrance.","followUpGoals":["interpret several details","choose and justify a responsibility","relate to experience","respond naturally to a different opinion"]}','r20-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');

