-- Existing tenants should immediately receive the full global speaking library.
INSERT OR REPLACE INTO tenant_learn_availability(tenant_id,school_level,domain,lesson_limit)
SELECT t.id,l.level,'speak',200
FROM tenants t CROSS JOIN (SELECT 'P5' level UNION ALL SELECT 'P6') l
WHERE t.status='active';
